// SPDX-License-Identifier: UNLICENSED
pragma solidity ^0.8.0;

import {Test} from "forge-std/Test.sol";
import {Wallet} from "../src/Wallet.sol";

contract InvMutTest is Test {
    uint256 internal constant VALUE_CAP = 1000000000000000000000000000000;
    Wallet c;

    function setUp() public {
        c = new Wallet();
    }

    function _run(uint256 amt) internal {
        amt = bound(amt, 0, 1000000000000000000000000000000);
        vm.deal(address(this), VALUE_CAP);
        vm.deal(address(c), VALUE_CAP);
        vm.assume(amt > 0);
        vm.assume(address(this).balance >= amt);
        uint beforeC = address(c).balance;
        uint beforeT = address(this).balance;
        try c.deposit{value: amt}() {} catch { return; }
        try c.refund() {} catch { return; }
        assertTrue(address(c).balance == beforeC && address(this).balance == beforeT);
    }

    function testFuzz_run(uint256 amt) public {
        _run(amt);
    }

    receive() external payable {}
}
